// Runs the repo's Python finders (detection/interactive.py) under Pyodide, off the page's thread.
// Messages out while it boots: progress {text}, ready {finders, about}, error {text}; the rest are the bridge's.
// A module worker: its imports are fetched with CORS, so the service worker can cache them.
import { bridge } from "./bridge.js";

const PYODIDE = "https://cdn.jsdelivr.net/pyodide/v314.0.7/full/";

const say = (text) => postMessage({ type: "progress", text });
let py;

async function boot() {
  const t0 = performance.now();
  say("Loading Python…");
  const { loadPyodide } = await import(PYODIDE + "pyodide.mjs");
  py = await loadPyodide({ indexURL: PYODIDE });
  say("Loading numpy, scipy, scikit-image…");
  // Only the packages the finders import are unpacked, and each native module loads the first time
  // Python imports it: loadPackage would load every module of every package and of its dependencies
  // up front, about 100 MB more memory. A package missing here fails loudly as an ImportError.
  const lock = (await (await fetch(PYODIDE + "pyodide-lock.json")).json()).packages;
  const vendored = (await (await fetch("vendor/wheels.json")).json()).map((w) => ({ url: new URL("vendor/" + w, self.location.href).href }));
  const wheels = ["numpy", "scipy", "scikit-image", "lazy-loader", "packaging", "pillow"]
    .map((n) => ({ url: PYODIDE + lock[n].file_name, sha256: lock[n].sha256 })).concat(vendored);
  const site = py.runPython("import sysconfig; sysconfig.get_path('purelib')");
  for (const buf of await Promise.all(wheels.map(fetchWheel))) py.unpackArchive(buf, "wheel", { extractDir: site });
  say("Loading the finders…");
  // Python modules are read straight from the repo's layout as they are imported: a new finder
  // file in detection/ ships with no list to update.
  py.globals.set("bases", py.toPy(["../detection/", "../src/"].map((b) => new URL(b, self.location.href).href)));
  py.runPython(`
import sys, os, importlib.util
from js import XMLHttpRequest

class RepoModules:
    """Imports a top-level module the runtime lacks from the site, the way it sits in the repo."""
    def find_spec(self, name, path=None, target=None):
        if path is not None or '.' in name:
            return None
        for base in bases:
            req = XMLHttpRequest.new(); req.open('GET', base + name + '.py', False); req.send()
            if req.status == 200:
                os.makedirs('/py', exist_ok=True); f = '/py/' + name + '.py'
                open(f, 'w').write(req.responseText)
                return importlib.util.spec_from_file_location(name, f)
        return None

sys.meta_path.append(RepoModules())
os.environ['NORFINDER_SRC'] = '/py'
import interactive, json
`);
  const finders = JSON.parse(py.runPython("json.dumps(interactive.FINDERS)"));
  const about = JSON.parse(py.runPython("json.dumps({f: interactive.describe(f) for f in interactive.FINDERS})"));
  postMessage({ type: "ready", finders, about, secs: (performance.now() - t0) / 1000 });
}

async function fetchWheel({ url, sha256 }) {
  const r = await fetch(url);
  if (!r.ok) throw new Error(`${url}: HTTP ${r.status}`);
  const buf = await r.arrayBuffer();
  if (sha256) {
    const got = [...new Uint8Array(await crypto.subtle.digest("SHA-256", buf))].map((b) => b.toString(16).padStart(2, "0")).join("");
    if (got !== sha256) throw new Error(`${url}: checksum mismatch`);
  }
  return buf;
}

const booted = boot().catch((e) => postMessage({ type: "error", text: String(e) }));

let answer;
async function handle(m) {
  await booted;
  answer ||= bridge(py, postMessage);
  answer(m);
}

let queue = Promise.resolve();
onmessage = (e) => {
  queue = queue.then(() => handle(e.data)).catch((err) => postMessage({ type: "error", text: String(err.message || err) }));
};
// The page's requests, answered by the Python session (detection/interactive.py) inside a Pyodide
// runtime that has already imported interactive and json. The worker runs it; the tests drive it
// outside a browser.
// Messages in: open {name, bytes}, detect {finder, overrides}, refilter {spec, seq}, memory.
// Messages out: progress {text}, opened {H, W, images}, detected {meta, seg}, filtered {fails, alone, seq},
// memory {used, heap, objects}.
export function bridge(py, post) {
  const say = (text) => post({ type: "progress", text });
  return function answer(m) {
    const t0 = performance.now();
    if (m.type === "open") {
      say("Reading the image and building the blue mask…");
      const path = "/tmp/" + m.name.replace(/[^\w.\-]/g, "_");
      py.FS.writeFile(path, new Uint8Array(m.bytes));
      py.globals.set("path", path);
      // the file is read once; kept, every image opened would stay in the worker's memory
      try { py.runPython("S = interactive.Session(path); H, W = S.caspr.shape; um = S.um"); } finally { py.FS.unlink(path); }
      // a handle to a Python object keeps it alive until it is destroyed, whatever JavaScript collects
      const im = py.runPython("S.images()"), images = im.toJs(); im.destroy();
      post({ type: "opened", H: py.globals.get("H"), W: py.globals.get("W"), um: py.globals.get("um"),
                images, secs: (performance.now() - t0) / 1000 }, [images.buffer]);
    } else if (m.type === "detect") {
      say("Finding candidates (the slow part)…");
      py.globals.set("finder", m.finder);
      py.globals.set("overrides", JSON.stringify(m.overrides || {}));
      const r = py.runPython("S.detect(finder, json.loads(overrides))"), s = r.get(1);
      const meta = JSON.parse(r.get(0)), seg = s.toJs(); s.destroy(); r.destroy();
      post({ type: "detected", meta, seg, secs: (performance.now() - t0) / 1000 }, [seg.buffer]);
    } else if (m.type === "refilter") {
      py.globals.set("spec", JSON.stringify(m.spec));
      const { fails, alone } = JSON.parse(py.runPython("sp = json.loads(spec); json.dumps(dict(fails=S.refilter(sp), alone=S.alone(sp)))"));
      post({ type: "filtered", fails, alone, seq: m.seq, ms: performance.now() - t0 });
    } else if (m.type === "memory") {
      // what Python holds after a collection: bytes in use by malloc, and live objects the collector
      // tracks; heap is the WebAssembly memory, which only ever grows to the high-water mark
      if (!py.globals.has("memory_use")) py.runPython(`
import ctypes, gc
class MallInfo(ctypes.Structure):
    _fields_ = [(n, ctypes.c_size_t) for n in 'arena ordblks smblks hblks hblkhd usmblks fsmblks uordblks fordblks keepcost'.split()]
libc = ctypes.CDLL(None); libc.mallinfo.restype = MallInfo
def memory_use():
    gc.collect()
    return json.dumps([libc.mallinfo().uordblks, len(gc.get_objects())])
`);
      const [used, objects] = JSON.parse(py.runPython("memory_use()"));
      post({ type: "memory", used, objects, heap: py._module.HEAPU8.byteLength });
    }
  };
}
// Keeps the third-party code the page runs (Pyodide and its packages from the CDN, and the
// wheels the build vendors under vendor/) in Cache Storage for 30 days, so a return visit starts
// without downloading ~50 MB again. The site's own files always come from the network, so a
// deploy is picked up on the next load.
const CACHE = "third-party-v1";
const MAX_AGE_MS = 30 * 24 * 3600 * 1000;
const STAMP = "x-nor-cached-at";

self.addEventListener("install", () => self.skipWaiting());
self.addEventListener("activate", (e) => e.waitUntil(self.clients.claim()));

self.addEventListener("fetch", (e) => {
  const req = e.request;
  const u = new URL(req.url);
  const own = u.origin === self.location.origin && !u.pathname.includes("/vendor/");
  // only the code the page runs is kept: never a user's own files, such as one read from Google Drive
  const code = !own && (u.origin === self.location.origin || u.hostname === "cdn.jsdelivr.net");
  if (req.method !== "GET" || !(own || code)) return;
  // own files are revalidated on every load: from the browser's plain HTTP cache a fresh page could
  // arrive with the previous release's stylesheet or scripts
  e.respondWith(own ? fetch(req, { cache: "no-cache" }) : cached(req));
});

async function cached(req) {
  const cache = await caches.open(CACHE);
  const hit = await cache.match(req.url);
  const at = hit && Number(hit.headers.get(STAMP));
  if (hit && at && Date.now() - at < MAX_AGE_MS) return hit;
  let res;
  try {
    res = await fetch(req);
  } catch (err) {
    if (hit) return hit; // offline: an expired copy beats nothing
    throw err;
  }
  if (res.ok && res.type !== "opaque") {
    const headers = new Headers(res.headers);
    headers.set(STAMP, String(Date.now()));
    const body = await res.clone().arrayBuffer();
    await cache.put(req.url, new Response(body, { status: res.status, statusText: res.statusText, headers }));
  }
  return res;
}
<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>NoR Finder</title>
<link rel="icon" href="data:,">
<link rel="stylesheet" href="style.css">
<script>
  // before the first paint, so a light-mode user never sees a dark flash
  try { const t = localStorage.getItem("nor-theme"); if (t) document.documentElement.dataset.theme = t; } catch { /* no storage */ }
</script>
</head>
<body>
<header>
  <img id="logo" src="logo.svg" alt="Sagol School of Neuroscience, Tel Aviv University">
  <h1>NoR Finder</h1>
  <button id="theme" class="icon" title="Switch between dark and light" aria-label="Switch between dark and light">
    <svg class="sun" viewBox="0 0 24 24" width="18" height="18"><circle cx="12" cy="12" r="4.5"/><path d="M12 2v2.5M12 19.5V22M2 12h2.5M19.5 12H22M4.9 4.9l1.8 1.8M17.3 17.3l1.8 1.8M4.9 19.1l1.8-1.8M17.3 6.7l1.8-1.8"/></svg>
    <svg class="moon" viewBox="0 0 24 24" width="18" height="18"><path d="M20 14.5A8 8 0 1 1 9.5 4a6.5 6.5 0 0 0 10.5 10.5z"/></svg>
  </button>
</header>

<div id="layout">
  <aside id="left">
    <section class="box" id="image-box">
      <div class="sec-head">
        <h2>Image</h2>
        <div class="split" id="load">
          <button id="load-main" class="primary">Load</button><details class="menu" id="load-menu"><summary class="primary" aria-label="Where to load from"></summary>
            <div class="pop right">
              <button class="item" data-src="local">From this computer</button>
              <button class="item" data-src="drive">From Google Drive</button>
            </div>
          </details>
        </div>
        <input id="file" type="file" accept=".tif,.tiff,.png" hidden>
      </div>
      <div id="thumb-wrap" hidden><canvas id="thumb"></canvas><div id="thumb-view"></div></div>
      <div id="file-name" class="dim">No image loaded</div>
      <div class="layers">
        <label title="Nav1.6: sodium channels at the node (shown red)"><input type="checkbox" id="show-r" class="ch r" checked>Nav1.6</label>
        <label title="Caspr: the paranodes either side of the node (shown green)"><input type="checkbox" id="show-g" class="ch g" checked>Caspr</label>
        <label title="DAPI: cell nuclei (shown blue)"><input type="checkbox" id="show-b" class="ch b">DAPI</label>
      </div>
    </section>

    <section class="box foldable">
      <div class="sec-head"><h2>Candidates finder</h2><button id="reset-detect" class="link" disabled>restore defaults</button></div>
      <select id="finder" disabled></select>
      <details id="about-box" class="fold">
        <summary>How it works</summary>
        <p id="finder-note" class="hint"></p>
      </details>
      <details id="settings-box" class="fold" open>
        <summary>Settings</summary>
        <div id="main-params"></div>
        <details id="advanced">
          <summary>Advanced <span class="dim">(every setting)</span></summary>
          <div id="detect-params"></div>
        </details>
      </details>
      <div class="row">
        <button id="find" class="primary" disabled>Find Candidates</button>
      </div>
    </section>

    <section class="box foldable">
      <div class="sec-head"><h2>Filters</h2><button id="reset-filters" class="link" disabled>restore defaults</button></div>
      <div id="filters"></div>
    </section>
  </aside>
  <div class="gutter" id="gutter-left" title="Drag to resize"></div>

  <main id="view">
    <div class="toolbar">
      <button id="switch" class="big" disabled>Item View</button>
      <details class="menu for-image" id="show-menu">
        <summary>Show</summary>
        <div class="pop">
          <div class="opt"><label><input type="checkbox" id="show-pass" checked> accepted</label>
            <input type="range" id="pass-w" min="0.5" max="4" step="0.5" title="Line width"><input type="color" id="pass-c" title="Colour"></div>
          <div class="opt"><label><input type="checkbox" id="show-fails" checked> rejected</label>
            <input type="range" id="fail-w" min="0.5" max="4" step="0.5" title="Line width"><input type="color" id="fail-c" title="Colour"></div>
          <label><input type="checkbox" id="show-nums" checked> candidate numbers</label>
          <label><input type="checkbox" id="show-letters" checked> rejection reasons</label>
          <label><input type="checkbox" id="show-lines" checked> measuring lines</label>
        </div>
      </details>
      <div class="for-items tabs" role="tablist">
        <button id="tab-pass" role="tab" class="on">Finalists <span id="n-pass"></span></button><button id="tab-fail" role="tab">Rejected <span id="n-fail"></span></button><button id="tab-miss" role="tab" title="NoRs you marked because the finder proposed nothing there (right-click the image)">Missing <span id="n-miss"></span></button>
      </div>
      <details class="menu for-items" id="card-menu">
        <summary>Options</summary>
        <div class="pop">
          <label class="num">context padding <input type="number" id="opt-pad" placeholder="auto" min="0" max="60" step="1"> px</label>
          <label><input type="checkbox" id="opt-align"> align to horizon</label>
          <label><input type="checkbox" id="opt-borders"> NoR borders</label>
          <label><input type="checkbox" id="opt-bars"> measurement bars</label>
          <label><input type="checkbox" id="opt-len-img"> lengths on the image</label>
          <label><input type="checkbox" id="opt-len-card"> lengths on the card</label>
          <label><input type="checkbox" id="opt-adjust"> length adjusters</label>
        </div>
      </details>
      <span class="grow"></span>
      <div class="for-image zoom" role="group" aria-label="Zoom">
        <button id="zoom-out" title="Zoom out" aria-label="Zoom out">−</button><span id="zoom-label">100%</span><button id="zoom-in" title="Zoom in" aria-label="Zoom in">+</button>
      </div>
    </div>
    <div id="busy" hidden><div id="scan-light"></div><span class="spin big"></span><div id="busy-text"></div><div id="busy-time"></div></div>

    <div id="image-view">
      <div id="scroller">
        <div id="empty">Load a three-channel ImageJ TIFF (Caspr green, Nav red, DAPI) or an RGB PNG, then press Find Candidates.<br>
          Python, which runs the finders, loads in the background meanwhile: about 50 MB on the first visit, then from this browser's cache for 30 days.</div>
        <div id="stage" hidden><canvas id="base"></canvas><svg id="overlay" xmlns="http://www.w3.org/2000/svg"></svg></div>
      </div>
    </div>

    <div id="items-view" hidden>
      <div id="list"></div>
    </div>
  </main>
  <div class="gutter" id="gutter-right" title="Drag to resize"></div>

  <aside id="right">
    <section class="box" id="selected-box">
      <div class="sec-head"><h2>Selected</h2>
        <div class="stepper"><button id="sel-prev" title="Previous candidate" aria-label="Previous candidate" disabled>‹</button><button id="sel-next" title="Next candidate" aria-label="Next candidate" disabled>›</button></div>
      </div>
      <div id="selected" class="dim">Click a candidate on the image.</div>
    </section>
    <section class="box">
      <h2>Summary</h2>
      <div id="summary" class="dim">No candidates yet.</div>
    </section>
    <section class="box" id="downloads">
      <h2>Downloads</h2>
      <button id="dl-cands" disabled>Candidates CSV</button>
      <button id="dl-summary" disabled>Summary CSV</button>
      <button id="dl-truth" disabled title="The candidates you voted on and your missing candidates, as a file; for an image from Google Drive, also opens a GitHub issue to submit it to the repo's ground truth">Ground truth</button>
    </section>
  </aside>
</div>

<footer id="statusbar">
  <span id="sb-file" class="seg">No image</span>
  <span id="sb-counts" class="seg"></span>
  <span id="sb-times" class="seg"></span>
  <span class="grow"></span>
  <span class="spin" id="spin"></span><span id="status">Starting…</span>
  <span id="sb-version" title="version 0.11006.17"></span>
</footer>

<dialog id="drive-dlg">
  <form method="dialog">
    <h2>Load from Google Drive</h2>
    <p class="hint">Paste the link of an image or a folder shared as "Anyone with the link".</p>
    <div class="drive-row"><input id="drive-link" type="text" placeholder="https://drive.google.com/…" autocomplete="off"><button id="drive-go" class="primary" type="button">Open</button></div>
    <div id="drive-path"></div>
    <div id="drive-list"></div>
    <div class="drive-row end"><span id="drive-msg" class="hint"></span><button value="close">Close</button></div>
  </form>
</dialog>
<div id="tip" hidden></div>
<div id="ctx" class="pop" role="menu" hidden><button class="item" role="menuitem" type="button"></button></div>
<div id="notice" role="alertdialog" aria-labelledby="notice-text" hidden><p id="notice-text"></p><button id="notice-ok" class="primary" type="button">OK</button></div>
<script src="config.js"></script>
<script src="drive.js"></script>
<script src="peek.js"></script>
<script src="app.js"></script>
</body>
</html>

