    const f = st.forced.get(c.i); if (!f) continue;
    const L = linesOf(c), px = measuresPx(c);
    labels.push({ id: st.numbers.get(c.i), x: c.cx, y: c.cy, label: f === "in" ? 1 : 0, source: "user",
