// Loads the page (real worker) from REPO with remote files served from a local copy over a simulated link of
// MBPS megabits/s (0 = no limit), and prints each status-bar text with the time it appeared.
//   node boot_timeline.mjs REPO MBPS [cpuSlowdown] [shot.png]
import { createRequire } from "node:module";
import { execSync } from "node:child_process";
import fs from "node:fs";
import http from "node:http";
import path from "node:path";
const require = createRequire(import.meta.url);
const pw = require(path.join(execSync("npm root -g").toString().trim(), "playwright"));
const [repo, mbps = "0", cpu = "1", shot] = process.argv.slice(2);
const CDN = path.join(path.dirname(new URL(import.meta.url).pathname), "cdn");
const TYPES = { ".html": "text/html", ".js": "text/javascript", ".mjs": "text/javascript", ".css": "text/css", ".json": "application/json", ".svg": "image/svg+xml", ".wasm": "application/wasm" };
const server = http.createServer((q, r) => {
  const f = path.join(repo, decodeURIComponent(new URL(q.url, "http://x").pathname));
  if (!fs.existsSync(f) || fs.statSync(f).isDirectory()) { r.writeHead(404); return r.end(); }
  r.writeHead(200, { "content-type": TYPES[path.extname(f)] || "application/octet-stream" }); fs.createReadStream(f).pipe(r);
});
await new Promise((ok) => server.listen(0, "[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]", ok));
const origin = `http://[REDACTED:env:CLOUDSDK_PROXY_ADDRESS]:${server.address().port}`;
const browser = await pw.chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1400, height: 900 } });
let linkFree = 0; const bps = (+mbps * 1e6) / 8;
await ctx.route(/^https:/, async (r) => {
  const u = r.request().url();
  if (!u.includes("cdn.jsdelivr.net")) return r.abort();
  const f = path.join(CDN, encodeURIComponent(u));
  if (!fs.existsSync(f)) execSync(`curl -sSfL --max-time 300 -o ${JSON.stringify(f)} ${JSON.stringify(u)}`);
  const body = fs.readFileSync(f);
  if (bps) {
    const now = Date.now(), start = Math.max(now, linkFree); linkFree = start + (body.length / bps) * 1000;
    await new Promise((ok) => setTimeout(ok, linkFree - now + 40));
  }
  const type = TYPES[path.extname(new URL(u).pathname)] || "application/octet-stream";
  return r.fulfill({ body, contentType: type, headers: { "access-control-allow-origin": "*", "content-length": String(body.length) } });
});
await ctx.addInitScript(() => { delete Navigator.prototype.serviceWorker; });
const page = await ctx.newPage();
if (+cpu > 1) { const c = await ctx.newCDPSession(page); await c.send("Emulation.setCPUThrottlingRate", { rate: +cpu }); }
page.on("pageerror", (e) => console.log("page error:", e.message));
page.on("console", (m) => { if (m.type() === "error") console.log("console:", m.text()); });
await page.exposeFunction("__log", (t, s) => console.log(`${(t / 1000).toFixed(1).padStart(6)} s  ${s}`));
await page.addInitScript(() => {
  addEventListener("DOMContentLoaded", () => {
    let last = "";
    const sb = document.querySelector("#statusbar");
    new MutationObserver(() => { const s = document.querySelector("#status").textContent; if (s !== last) { last = s; window.__log(performance.now(), s); } })
      .observe(sb, { subtree: true, childList: true, characterData: true });
  });
});
await page.goto(origin + "/web/index.html");
await page.waitForFunction(() => !document.querySelector("#finder").disabled, null, { timeout: 600000 });
if (shot) await page.screenshot({ path: shot });
await browser.close(); server.close();

